package term

// Snapshot tests that are not in upstream `codespan-reporting/tests/term.rs`.
//
// The expected outputs in testdata/snapshots_extra are generated by
// codespan-reporting 0.13.1 (Rust) from the same inputs, with the tests in
// testdata/snapshots_extra/rust/tests/extra.rs:
//
//	cd testdata/snapshots_extra/rust
//	INSTA_UPDATE=always cargo test
//
// When adding a case here, add the same module to extra.rs and regenerate.

import (
	"testing"

	"github.com/nobuyuki/srcspan/diagnostic"
	"github.com/nobuyuki/srcspan/files"
	"github.com/nobuyuki/srcspan/internal/unindent"
)

func TestExtraSnapshots(t *testing.T) {
	runSnapshotCases(t, extraSnapshotCases, "snapshots_extra", "extra")
}

var extraSnapshotCases = []snapshotCase{
	// A multi-line label ends on the line where another multi-line label starts.
	// Covers the branch in `RenderSnippetSource` that draws an inner gutter
	// column for a top label after the current one, or for a bottom label
	// before it.
	{
		name:   "multiline_end_and_start_on_same_line",
		config: DefaultConfig,
		data: func() *testData {
			file := files.NewSimpleFile("main.rs", unindent.Unindent("\n                    fn main() {\n                        let x = foo(\n                            1,\n                        ); let y = bar(\n                            2,\n                        );\n                    }\n                "))

			diagnostics := []*diagnostic.Diagnostic{
				diagnostic.NewError().
					WithMessage("mismatched types").
					WithLabels([]diagnostic.Label{
						diagnostic.NewPrimary(0, files.NewRange(24, 45)).
							WithMessage("expected `u32`"),
						diagnostic.NewSecondary(0, files.NewRange(55, 76)).
							WithMessage("found `i32`"),
					}),
			}

			return &testData{&file, diagnostics}
		},
		tests: []snapshotTest{richColor, mediumColor, shortColor, richNoColor, mediumNoColor, shortNoColor, richASCIINoColor},
	},
}
